content.content:
84	// DetectGroup calls the Nexus REST API to determine whether the registry points
85	// to a group repository and, if so, returns its member repositories.
86	//
87	// Returns nil, nil when the manager answered and the repository is not a group,
88	// a non-nil empty list for a group it listed with no member, and an error when it
89	// could not be asked or refused to list the members (a *MembersRefusedError,
90	// errors.Is ErrMembersRefused). Those are not the same thing: the caller caches
91	// the settled answers and must not cache an error, or one unreachable minute (or
92	// one refused account) erases what was last known (D23).
93	func (n *NexusDetector) DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) {
94		// Resolve which URL to use for the Nexus API call.
95		apiBase := info.ManagementURL
96		if apiBase == "" {
97			apiBase = info.URL
98		}
99	
100		host, repoName, err := parseNexusURL(apiBase)
101		if err != nil {
102			// Not an error: a URL that is not a Nexus repository path is a settled
103			// answer, not a failure to reach one.
104			// The cause only: a URL that does not parse may hold a password, and
105			// url.Error repeats it whole.
106			var ue *url.Error
107			if errors.As(err, &ue) {
108				err = ue.Err
109			}
110			log.Printf("INFO [registrymgr/nexus] cannot parse Nexus URL: %v", err)
111			return nil, nil
112		}
113	
114		hasAuth := info.Username != "" && info.Password != ""
115		log.Printf("INFO [registrymgr/nexus] detecting group for %q (auth=%v)", repoName, hasAuth)
116	
117		// Step 1: generic endpoint — confirms this repo is a group, gets its format,
118		// and may already include memberNames in the attributes field (no admin privilege needed).
119		repoType, repoFormat, members, err := n.fetchRepoMeta(ctx, host, repoName, info)
120		if err != nil {
121			return nil, err
122		}
123		if repoType != "group" {
124			return nil, nil
125		}
126	
127		if len(members) > 0 {
128			log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(members))
129			return members, nil
130		}
131	
132		// Step 2: format-specific endpoint — requires nx-repository-admin privilege
133		// but returns memberNames reliably on Nexus instances that support it.
134		members, err = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
135		if err != nil {
136			return nil, err
137		}
138		log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(members))
139		return members, nil
140	}
141	
142	// fetchRepoMeta calls the generic /v1/repositories/{name} endpoint.
143	// Returns type, format and any memberNames found in attributes, or an error when
144	// the manager could not be asked.
145	// Some Nexus deployments include memberNames in attributes.group without requiring admin privilege.
146	func (n *NexusDetector) fetchRepoMeta(ctx context.Context, host, repoName string, info RegistryInfo) (repoType, format string, members []GroupMember, err error) {
147		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s", host, repoName)
148		body, err := n.nexusGET(ctx, endpoint, info)
149		if err != nil {
150			log.Printf("INFO [registrymgr/nexus] meta unreachable %q: %v", endpoint, err)
151			return "", "", nil, fmt.Errorf("reading %s: %w", endpoint, err)
152		}
153		if len(bytes.TrimSpace(body)) == 0 {
154			log.Printf("INFO [registrymgr/nexus] meta %q: empty reply", repoName)
155			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errEmptyReply)
156		}
157		var result struct {
158			Type   string `json:"type"`
159			Format string `json:"format"`
160			Group  struct {
161				MemberNames []string `json:"memberNames"`
162			} `json:"group"`
163			Attributes struct {
164				Group struct {
165					MemberNames []string `json:"memberNames"`
166				} `json:"group"`
167			} `json:"attributes"`
168		}
169		if err := json.Unmarshal(body, &result); err != nil {
170			log.Printf("INFO [registrymgr/nexus] meta parse error for %q: %v", repoName, err)
171			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, err)
172		}
173		if result.Type == "" {
174			// Valid JSON that is not a repository document: `{}`, `null`.
