198	// The first attempt decides. The anonymous retry (D156) only changes the outcome
199	// by succeeding: whatever it gets otherwise, the account was refused and that is
200	// the actionable fact.
201	func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) ([]GroupMember, error) {
202		if format == "" {
203			format = "docker"
204		}
205		// The format comes from the server: it stays one path segment.
206		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s/group/%s", host, url.PathEscape(format), repoName)
207		body, err := n.nexusGET(ctx, endpoint, info)
208		if err != nil {
209			firstErr := err
210			// When auth is present but the request fails, retry anonymously.
211			// Some Nexus instances allow anonymous read of the group admin endpoint.
212			// A refused redirect to another origin is not such a failure: the
213			// detection stops there (DEVDESK-412), no silent anonymous retry.
214			if info.Username != "" && info.Password != "" && !errors.Is(err, oci.ErrOffOriginRedirect) {
215				anonInfo := RegistryInfo{URL: info.URL, ManagementURL: info.ManagementURL}
216				body, err = n.nexusGET(ctx, endpoint, anonInfo)
217				if err != nil {
218					log.Printf("INFO [registrymgr/nexus] anonymous retry for %q failed: %v", repoName, err)
219				}
220			}
221			if err != nil {
222				return nil, membersFailure(host, repoName, endpoint, firstErr, info.Username != "" && info.Password != "")
223			}
224		}
225		names, err := parseGroupMembers(body)
226		if err != nil {
227			log.Printf("INFO [registrymgr/nexus] members %q: %v", repoName, err)
228			return nil, fmt.Errorf("reading the members of group %q: %w", repoName, err)
229		}
230		return memberList(info.URL, names), nil
231	}
232	
233	// membersFailure logs and types the failure of the first attempt on the format
234	// endpoint: a refusal when the manager refused the account, the error itself
235	// otherwise. The returned error holds the group and the status, never the URL.
236	func membersFailure(host, repoName, endpoint string, err error, hasAuth bool) error {
237		if status, ok := refusedStatus(err); ok {
238			log.Printf("INFO [registrymgr/nexus] members refused %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
239			// The cause is the status error itself, so the refusal never carries a
240			// repositoryNotFoundError nor anything of the body.
241			// refusedStatus found one, so errors.As cannot fail.
242			var cause *oci.StatusError
243			errors.As(err, &cause)
244			return &MembersRefusedError{Group: repoName, Status: status, Anonymous: !hasAuth, Cause: cause}
245		}
246		if errors.Is(err, oci.ErrOffOriginRedirect) {
247			// The advice above is for an account Nexus refused, not for this.
248			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — redirect to another origin refused (the registry URL may need to be the one Nexus serves)", endpoint, err)
249		} else {
250			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v", endpoint, err)
251		}
252		return fmt.Errorf("reading the members of group %q: %w", repoName, err)
253	}

