127		if len(members) > 0 {
128			log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(members))
129			return members, nil
130		}
131	
132		// Step 2: format-specific endpoint — requires nx-repository-admin privilege
133		// but returns memberNames reliably on Nexus instances that support it.
134		members, err = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
135		if err != nil {
136			return nil, err
137		}
138		log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(members))
